?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>Editar Concurso</title><?php include 'includes_painel/head.php'; ?><?php include '_form_style.php'; ?></head><body><?php include 'includes_painel/header.php'; ?><div class="crud"><div class="card"><h1>Editar Concurso</h1><form method="post"><div class="grid"><div class="campo"><label>Nome</label><input name="nome" required value="<?=h($row['nome'])?>"></div><div class="campo"><label>Órgão</label><input name="orgao" value="<?=h($row['orgao']??'')?>"></div><div class="campo"><label>Cargo</label><input name="cargo" value="<?=h($row['cargo']??'')?>"></div><div class="campo"><label>Escolaridade</label><input name="escolaridade" value="<?=h($row['escolaridade']??'')?>"></div><div class="campo"><label>Ano</label><input type="number" name="ano" value="<?=h($row['ano']??'')?>"></div><div class="campo"><label>Edital</label><input name="edital" value="<?=h($row['edital']??'')?>"></div><div class="campo"><label>Status</label><select name="status"><?php foreach(['Aberto','Em andamento','Encerrado','Suspenso'] as $op):?><option <?=($row['status']??'')===$op?'selected':''?>><?=h($op)?></option><?php endforeach;?></select></div></div><div class="acoes"><button class="btn salvar">Salvar alterações</button><a class="btn voltar" href="lista_concursos.php">Cancelar</a></div></form></div></div></body></html>
